__int128 mod_pow(__int128 base, long long exp, __int128 mod) {
    __int128 result = 1;
    __int128 b = base % mod;
    while (exp > 0) {
        if (exp & 1) result = (result * b) % mod;
        b = (b * b) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
